select @tu_ngay as tu_ngay, @den_ngay as den_ngay
exec zrpt_cashfund @tu_ngay, @den_ngay, @ma_kh, @ma_loai, @tinh_chat, @mau_bc, @@unit, @@language, @@userID, @@admin

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_kh');
	changeLookupReadonly(f, 'ma_loai');
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._hiddenForms = [];
			g._alterTitle = [null, [['%y1', f.getItem('tu_ngay').value, true], ['%y2', f.getItem('den_ngay').value, true]]];
			
			break;
		default:
			break;
	}
}

function remove$GridReport$Filter(g) {
	var r = ('lai_suat0, du_no0, ps0, lai_suat, du_no, ps').split(','), name, field;
	for (i = 0; i < r.length; i++) {
		for (var j = 0; j < g._filter.length; j++) {
			name = $func.trim(r[i]);
			field = $func.findField(name, g._fields)
			if (field) field.FilterPanelValue = '';
			if (g._filter[j].match(/^(\w+):/)[1] == name) {
				Array.removeAt(g._filter, j);
				break;
			}
		}
	}
}

		
	

